// Firebase token verify
const body = $input.first().json.body;
const headers = $input.first().json.headers;
const token = (headers.authorization || headers.Authorization || '').replace('Bearer ','');
if (!token) return [{json:{success:false,message:'No token'}}];
try {
  const res = await fetch('https://identitytoolkit.googleapis.com/v1/accounts:lookup?key=AIzaSyCHXYfgfM83wpHemsSySFbV6KLrGF5RAaw', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({idToken: token})
  });
  const data = await res.json();
  if (data.users && data.users.length > 0) {
    return [{json:{success:true, uid: data.users[0].localId, email: data.users[0].email}}];
  }
  return [{json:{success:false, message:'Invalid token'}}];
} catch(e) { return [{json:{success:false, message:e.message}}]; }

const headers = $input.first().json.headers;
const body = $input.first().json.body;
const token = (headers.authorization||headers.Authorization||'').replace('Bearer ','');
try {
  const res = await fetch('https://identitytoolkit.googleapis.com/v1/accounts:lookup?key=AIzaSyCHXYfgfM83wpHemsSySFbV6KLrGF5RAaw',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idToken:token})});
  const data = await res.json();
  if (!data.users||!data.users.length) return [{json:{_action:'error',success:false,message:'Unauthorized'}}];
  const uid = data.users[0].localId;
  if (body && body.business_name) {
    const cid = (body.business_name||'c').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'')+'_'+Date.now().toString(36);
    return [{json:{...body, client_id: body.client_id||cid, firebase_uid: uid, _action:'create'}}];
  }
  return [{json:{_action:'list', firebase_uid: uid}}];
} catch(e){return [{json:{_action:'error',success:false,message:e.message}}];}

